TS async iterator example:

const client = new Redwood.EmbeddingsClient();
for await (const page of client.listEmbeddingsIterator({ query: 'finserv corpus', pageSize: 128 })) {
  for (const emb of page.items) {
    process(emb)
  }
}

Go iterator example:

ctx := context.Background()
client := redwood.NewEmbeddingsClient()
it := client.ListEmbeddingsIterator(ctx, redwood.ListOptions{Query: "corpus", PageSize: 128})
for it.Next() {
  page := it.Page()
  for _, emb := range page.Items {
    process(emb)
  }
}
if err := it.Err(); err != nil {
  // handle
}
